-- DAG seed data, exported from the live database on 2026-09-06.
-- Generated by scripts/export-seed.mjs (npm run backup) — do not edit by hand.
-- Run after schema.sql. Safe to re-run: every insert upserts on its key.
--
-- Poll votes are not exported. voter_key is readable by no role, and a live tally is not
-- seed data.

-- events (10)
on conflict (id) do update set
  event_name = excluded.event_name, date = excluded.date, description = excluded.description,
  season = excluded.season, status = excluded.status, event_type = excluded.event_type,
  register_url = excluded.register_url, game_type = excluded.game_type, recording_url = excluded.recording_url;

-- leaderboard rows (32)
on conflict (id) do update set
  event_name = excluded.event_name, season = excluded.season, rank = excluded.rank,
  player_name = excluded.player_name, points = excluded.points,
  game_type = excluded.game_type, team_name = excluded.team_name;

-- hall of fame: no rows

-- polls (3)
on conflict (id) do update set
  type = excluded.type, title = excluded.title, description = excluded.description,
  season = excluded.season, status = excluded.status, ends_at = excluded.ends_at, form_url = excluded.form_url;

-- poll options (12)
on conflict (poll_id, id) do update set
  label = excluded.label, position = excluded.position;

-- members (6)
on conflict (name) do update set
  role = excluded.role, games = excluded.games, is_founder = excluded.is_founder,
  is_president = excluded.is_president, note = excluded.note,
  instagram = excluded.instagram, discord = excluded.discord, position = excluded.position;
